={{ (() => {
  const body = $('Lead Form Webhook').first().json.body || {};
  const cfg = $('Config').first().json;
  const str = v => (v === undefined || v === null) ? '' : String(v).trim();
  const errors = {};

  // Honeypot: a hidden "website" field that humans never fill in
  const isSpam = str(body.website || body._gotcha) !== '';

  const name = str(body.name || body.full_name).replace(/\s+/g, ' ');
  const email = str(body.email).toLowerCase();
  const rawPhone = str(body.phone || body.whatsapp);
  let phone = rawPhone.replace(/[^\d+]/g, '');
  if (phone.startsWith('+')) phone = phone.slice(1);
  else if (phone.startsWith('0')) phone = cfg.default_country_code + phone.slice(1);

  if (!name) errors.name = 'Required';
  else if (name.length > 120) errors.name = 'Must be 120 characters or fewer';
  if (!email) errors.email = 'Required';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.email = 'Not a valid email address';
  if (rawPhone && !/^\d{8,15}$/.test(phone)) errors.phone = 'Must contain 8-15 digits including country code';

  return {
    valid: Object.keys(errors).length === 0,
    is_spam: isSpam,
    errors,
    lead: {
      lead_id: 'LEAD-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + $execution.id,
      submitted_at: $now.toISO(),
      name,
      email,
      phone,
      company: str(body.company).slice(0, 120),
      message: str(body.message).slice(0, 2000),
      source: str(body.source || body.page_url) || 'website',
      utm_source: str(body.utm_source),
      utm_campaign: str(body.utm_campaign)
    }
  };
})() }}

={{ (() => {
  const l = $('Validate & Normalize Lead').first().json.result.lead;
  const saved = $json.crm_saved !== false;
  return [
    saved ? '🔥 *New lead: reply within 5 minutes!*' : '🚨 *New lead: NOT saved to CRM, add it manually!*',
    '',
    '👤 *Name:* ' + l.name,
    '🏢 *Company:* ' + (l.company || '-'),
    '📧 *Email:* ' + l.email,
    '📱 *Phone:* ' + (l.phone ? '+' + l.phone + '  →  https://wa.me/' + l.phone : '-'),
    '💬 *Message:* ' + (l.message ? l.message.slice(0, 600) : '-'),
    '🌐 *Source:* ' + l.source + (l.utm_campaign ? ' / ' + l.utm_campaign : ''),
    '🕒 *Submitted:* ' + DateTime.fromISO(l.submitted_at).toFormat('dd LLL yyyy, HH:mm'),
    '🆔 ' + l.lead_id,
    '',
    saved ? '📊 CRM: ' + $('Config').first().json.crm_url : '⚠️ CRM write failed after retries. The team has been alerted by email.'
  ].join('\n');
})() }}

={{ (() => {
  const t = $('On Workflow Error').first().json;
  const msg = t.execution?.error?.message ?? t.trigger?.error?.message ?? '';
  if (msg.includes('[CRITICAL]')) return 'CRITICAL';
  if (msg.includes('[WARNING]')) return 'WARNING';
  return 'ERROR';
})() }}

